import{_ as s,a0 as n,w as l,s as m,ao as i,I as a,x as o,a1 as e,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const R=JSON.parse('{"title":"如何提升自動化的 ROI：4 個小提示 | LCTT x X-CMD","titleTemplate":false,"description":"如何提升自動化的 ROI：4 個小提示 | LCTT (201807) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何提升自動化的 ROI：4 個小提示 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何提升自動化的 ROI：4 個小提示 | LCTT (201807) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201807/20171116 How to improve ROI on automation- 4 tips","title":"如何提升自動化的 ROI：4 個小提示","tag":"201807","desc":""},"relativePath":"201807/20171116 How to improve ROI on automation- 4 tips.md","filePath":"[post].md"}'),d={name:"201807/20171116 How to improve ROI on automation- 4 tips.md"};function O(u,t,C,f,T,I){const r=n("Link");return l(),m("div",null,[t[17]||(t[17]=i('<h1 id="如何提升自動化的-roi-4-個小提示" tabindex="-1">如何提升自動化的 ROI：4 個小提示 <a class="header-anchor" href="#如何提升自動化的-roi-4-個小提示" aria-label="Permalink to “如何提升自動化的 ROI：4 個小提示”">​</a></h1><blockquote><p>想要在你的自動化項目上達成強 RIO？採取如下步驟來規避失敗。</p></blockquote><p><img src="https://enterprisersproject.com/sites/default/files/styles/620x350/public/cio_it_investments_2.png?itok=Ut1XIIBN" alt=""></p><p>在過去的幾年間，有關自動化技術的討論已經很多了。COO 們和運營團隊（事實上還有其它的業務部門）對於可以重新定義成本隨着工作量的增加而增加的這一事實而感到震驚。</p><p><ruby>機器人流程自動化<rt>Robotic Process Automation</rt></ruby>（RPA）似乎預示着運營的<ruby>聖盃<rt>Holy Grail</rt></ruby>：“我們提供了開箱即用的功能來滿足你的日常操作所需 —— 檢查電子郵件、保存附件、取數據、更新表格、生成報告、文件以及目錄操作。構建一個機器人就像配置這些功能一樣簡單，然後用機器人將這些操作鏈接到一起，而不用去請求 IT 部門來構建它們。”這是一個多麼誘人的話題。</p><p>低成本、幾乎不出錯、非常遵守流程 —— 對 COO 們和運營領導來説，這些好處真實可及。RPA 工具承諾，它從運營中節省下來的費用就足夠支付它的成本（有一個短的回報期），這一事實使得業務的觀點更具有吸引力。</p><p>自動化的談論都趨向於類似的話題：COO 們和他們的團隊想知道，自動化操作能夠給他們帶來什麼好處。他們想知道 RPA 平台特性和功能，以及自動化在現實中的真實案例。從這一點到概念驗證的實現過程通常很短暫。</p>',7)),a("p",null,[a("strong",null,[t[1]||(t[1]=o("[ 在實現人工智能技術方面的建議，可以查看我們相關的文章，",-1)),e(r,{href:"https://enterprisersproject.com/article/2017/11/crafting-your-ai-strategy-3-tips?sc_cid=70160000000h0aXAAQ"},{default:p(()=>[...t[0]||(t[0]=[o("制定你的人工智能策略：3 個小提示",-1)])]),_:1}),t[2]||(t[2]=o("]",-1))]),t[3]||(t[3]=o("。",-1))]),t[18]||(t[18]=i('<p>但是自動化帶來的現實好處有時候可能比你所預期的時間要晚。採用 RPA 的公司在其實施後可能會對它們自身的 ROI 提出一些質疑。一些人沒有看到預期之中的成本節省，並對其中的原因感到疑惑。</p><h3 id="你是不是自動化了錯誤的東西" tabindex="-1">你是不是自動化了錯誤的東西？ <a class="header-anchor" href="#你是不是自動化了錯誤的東西" aria-label="Permalink to “你是不是自動化了錯誤的東西？”">​</a></h3><p>在這些情況下，自動化的願景和現實之間的差距是什麼呢？我們來分析一下它，在決定去繼續進行一個自動化驗證項目（甚至是一個成熟的實踐）之後，我們來看一下通常會發生什麼。</p><p>在確定實施自動化所採用的路徑之後，COO 一般會問運營領導和他的團隊們，應該在哪個流程或者任務上實施自動化。雖然從原則上説應該鼓勵他們參與進來，但是有時候這種方式產生的決策往往會產生一個次優選擇。原因如下：</p><p>首先，團隊領導經常會是“視野較窄”：他們對自己的流程和任務非常熟悉，但是對他們不參與的流程和任務並不是那麼熟悉（特別是在他們沒有太多運營經驗的情況下）。這意味着他們在自己的工作領域內可能會找出比較適合自動化的候選者，但是在跨整個運營的其它領域中可能並不一定會找出最適合的。另外其它的像“我希望我的流程成為第一個實施自動化的候選者”這樣的“軟性”因素也會影響決定。</p><p>其次，候選流程的選擇有時候會被自動化特性和能力的匹配度所支配，而不是根據自動化所帶來的價值所決定的。一個常見的誤解是，任何包括像電子郵件或目錄監視、下載、計算等活動的任務都是自動化的最佳候選者。如果對這些任務實施自動化不能為組織產生價值，那麼它們就不是正確的候選者。</p><p>那麼，對於領導們來説，怎麼才能確保實施自動化能夠帶來他們想要的 ROI 呢？實現這個目標有四步：</p><h3 id="_1-教育團隊" tabindex="-1">1. 教育團隊 <a class="header-anchor" href="#_1-教育團隊" aria-label="Permalink to “1. 教育團隊”">​</a></h3><p>在你的團隊中，從 COO 職位以下的人中，很有可能都聽説過 RPA 和運營自動化。同樣很有可能他們都有許多的問題和擔心。在你開始啓動實施之前解決這些問題和擔心是非常重要的。</p><p>對運營團隊進行積極的教育可以大大地提升他們對自動化的熱情和信心。培訓主要關注於自動化和機器人是什麼，它們在流程中一般扮演什麼樣的角色，哪個流程和任務最適合自動化，以及自動化的預期好處是什麼。</p><p><strong>建議</strong>：邀請你的自動化合作夥伴去進行這些團隊教育工作，你要有所控制：他們可能會非常樂意幫助你。在領導層將這些傳播到更大範圍的團隊之前，你應該對他們的教育內容進行把關。</p><p>“實施自動化的第一步是更好地理解你的流程。”</p><h3 id="_2-審查內部流程" tabindex="-1">2. 審查內部流程 <a class="header-anchor" href="#_2-審查內部流程" aria-label="Permalink to “2. 審查內部流程”">​</a></h3><p>實施自動化的第一步是更好地理解你的流程。每個 RPA 實施之前都應該進行流程清單、動作分析、以及成本/價值的繪製練習。</p><p>這些練習對於理解流程中何處產生價值（或成本，如果沒有價值的情況下）是至關重要的。並且這些練習需要在每個流程或者每個任務這樣的粒度級別上來做。</p><p>這將有助你去識別和優先考慮最合適的自動化候選者。由於能夠或者可能需要自動化的任務數量較多，流程一般需要分段實施自動化，因此優先級很重要。</p><p><strong>建議</strong>：設置一個小的工作團隊，每個運營團隊都參與其中。從每個運營團隊中提名一個協調人 —— 一般是運營團隊的領導或者團隊管理者。在團隊級別上組織一次研討會，去構建流程清單、識別候選流程、以及推動購買。你的自動化合作夥伴很可能有“加速器” —— 調查問卷、計分卡等等 —— 這些將幫助你加速完成這項活動。</p><h3 id="_3-為優先業務提供強有力的指導" tabindex="-1">3. 為優先業務提供強有力的指導 <a class="header-anchor" href="#_3-為優先業務提供強有力的指導" aria-label="Permalink to “3. 為優先業務提供強有力的指導”">​</a></h3><p>實施自動化經常會涉及到在運營團隊之間，基於業務價值對流程選擇和自動化優先級上要達成共識（有時候是打破平衡）雖然團隊的參與仍然是分析和實施的關鍵部分，但是領導仍然應該是最終的決策者。</p><p><strong>建議</strong>：安排定期會議從工作團隊中獲取最新信息。除了像推動達成共識和購買之外，工作團隊還應該在團隊層面上去查看領導們關於 ROI、平台選擇、以及自動化優先級上的指導性決定。</p><h3 id="_4-應該推動-cio-和-coo-的緊密合作" tabindex="-1">4. 應該推動 CIO 和 COO 的緊密合作 <a class="header-anchor" href="#_4-應該推動-cio-和-coo-的緊密合作" aria-label="Permalink to “4. 應該推動 CIO 和 COO 的緊密合作”">​</a></h3><p>當運營團隊和技術團隊緊密合作時，自動化的實施將異常順利。COO 需要去幫助推動與 CIO 團隊的合作。</p><p>COO 和其他運營領導人的參與和監督對成功實施自動化是至關重要的。</p><p><strong>建議</strong>：COO 和 CIO 團隊應該與第三方的自動化合作夥伴共同設立一個聯合工作組（一個“戰場”）。對每個參與者的責任進行明確的界定並持續跟蹤。理想情況下，COO 和 CIO 應該至少有一個投入到聯合工作組中，至少在初始發佈中應該是這樣。</p><p>自動化可以為組織創造重要的價值。然而為了在自動化中獲得最優的投資回報，CIO 們必須在“入坑”之前做好規劃。</p><hr>',26)),a("p",null,[t[5]||(t[5]=o("via: ",-1)),e(r,{href:"https://enterprisersproject.com/article/2017/11/how-improve-roi-automation-4-tips"},{default:p(()=>[...t[4]||(t[4]=[o("https://enterprisersproject.com/article/2017/11/how-improve-roi-automation-4-tips",-1)])]),_:1})]),a("p",null,[t[9]||(t[9]=o("作者：",-1)),e(r,{href:"https://enterprisersproject.com/user/rajesh-kamath"},{default:p(()=>[...t[6]||(t[6]=[o("Rajesh Kamath",-1)])]),_:1}),t[10]||(t[10]=o(" 譯者：",-1)),e(r,{href:"https://github.com/qhwdw"},{default:p(()=>[...t[7]||(t[7]=[o("qhwdw",-1)])]),_:1}),t[11]||(t[11]=o(" 校對：",-1)),e(r,{href:"https://github.com/wxy"},{default:p(()=>[...t[8]||(t[8]=[o("wxy",-1)])]),_:1})]),a("p",null,[t[14]||(t[14]=o("本文由 ",-1)),e(r,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[12]||(t[12]=[o("LCTT",-1)])]),_:1}),t[15]||(t[15]=o(" 原創編譯，",-1)),e(r,{href:"https://linux.cn/"},{default:p(()=>[...t[13]||(t[13]=[o("Linux中國",-1)])]),_:1}),t[16]||(t[16]=o(" 榮譽推出",-1))])])}const b=s(d,[["render",O]]);export{R as __pageData,b as default};
